import{_ as t,o as e,c as _,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/50-貌合神离：一场两败俱伤的妥协.md","filePath":"books/attached/50-貌合神离：一场两败俱伤的妥协.md","lastUpdated":1794298621000}'),i={name:"books/attached/50-貌合神离：一场两败俱伤的妥协.md"};function r(l,a,p,s,d,n){return e(),_("div",null,[...a[0]||(a[0]=[o('<h3 id="貌合神离-一场两败俱伤的妥协" tabindex="-1">貌合神离：一场两败俱伤的妥协 <a class="header-anchor" href="#貌合神离-一场两败俱伤的妥协" aria-label="Permalink to &quot;貌合神离：一场两败俱伤的妥协&quot;">​</a></h3><p>那么，回避型依恋风格的人到底是如何抑制自己的情感，并且在恋爱中疏离对方的呢？接下来，我们就来看看他们与亲密之人保持距离的方法，这些方法可谓是各式各样，从一些日常的去激活策略，到总体的认知和信念层面，无所不用其极。</p><ul><li><p>麦克（Mike），27岁，他总觉得在一起五年的伴侣好像配不上他。虽然他们深爱着彼此，他总是对现在的恋爱关系有些隐隐的不满。他心中总是有种挥之不去的失落，总觉得自己能够遇到更优秀的人。</p></li><li><p>卡亚（Kaia），31岁，跟男友同居两年的她，却依然怀念着单身时期无忧无虑的日子。她表面上似乎忘却了那种自由的生活，但事实上，恋爱中的她感到又孤独又压抑。</p></li><li><p>斯塔夫罗斯（Stavros），40岁，他是个风度翩翩的精明企业家，非常渴望婚姻与孩子。他对于未来的妻子有着很明确的要求，她必须得非常年轻，不能超过28岁，必须得很漂亮，和他一样事业心强。还有一条也很重要，她必须得愿意和他一同回到希腊老家。不过，苦苦寻觅十多年，他依然没有找到满意的人选。</p></li><li><p>汤姆，49岁，与妻子结婚几十年了，妻子曾经是她深爱的女神。但是现在，他感觉被婚姻枷锁压得喘不过气，只想抓住一切机会逃离妻子，不管是独自旅行，还是与男性朋友应酬都好。</p></li></ul><p>上面提到的人们，都属于回避型依恋风格。他们即使处于恋爱状态，也会感到深深的孤独感。安全型依恋风格的人群很容易接纳自己恋人的好与坏，很容易对伴侣表现依恋，也相信自己的恋人是独一无二的。而对于回避型人群来说，这看似容易的一切反而是个巨大的生活挑战。回避型依恋风格的人，虽然处于恋爱关系中，却依然会和恋人保持距离，甚至随时准备逃走。他们很难产生那种全身心投入恋爱的感觉，也并不会感觉找到伴侣就是找到了温暖的家。</p>',4)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
